/// Looks up a language table.
#[must_use]
pub fn lookup(lang: &str) -> Option<&'static [&'static str]> {
    match lang {
        "gl" => Some(GL),
        "hi" => Some(HI),
        "hu" => Some(HU),
        "hy" => Some(HY),
        "id" => Some(ID),
        "it" => Some(IT),
        "nl" => Some(NL),
        _ => None,
    }
}
